import java.io.*;
import java.net.*;
import java.security.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import javax.crypto.*;
import javax.crypto.spec.*;
import java.util.Base64;
import java.util.logging.*;

public class CryptoKeyServer {
    private static final Logger logger = Logger.getLogger(CryptoKeyServer.class.getName());
    private final ExecutorService executor = Executors.newFixedThreadPool(4);
    private final AtomicBoolean shuttingDown = new AtomicBoolean(false);
    private final ConcurrentHashMap<String, KeyRecord> keyStore = new ConcurrentHashMap<>();
    private ServerSocket serverSocket;
    private final Object shutdownLock = new Object();

    static class KeyRecord {
        final String keyId;
        final String algorithm;
        final byte[] encodedKey;
        final String metadata;

        KeyRecord(String keyId, String algorithm, byte[] encodedKey, String metadata) {
            this.keyId = keyId;
            this.algorithm = algorithm;
            this.encodedKey = encodedKey;
            this.metadata = metadata;
        }
    }

    public void start(int port) throws IOException {
        serverSocket = new ServerSocket(port);
        Runtime.getRuntime().addShutdownHook(new Thread(this::gracefulShutdown));
        logger.info("CryptoKeyServer started on port " + port);

        while (!shuttingDown.get()) {
            try {
                Socket client = serverSocket.accept();
                executor.submit(() -> handleClient(client));
            } catch (IOException e) {
                if (!shuttingDown.get()) {
                    logger.warning("Accept failed: " + e.getMessage());
                }
            }
        }
    }

    private void handleClient(Socket client) {
        try (BufferedReader in = new BufferedReader(new InputStreamReader(client.getInputStream()));
             PrintWriter out = new PrintWriter(client.getOutputStream(), true)) {

            String requestLine = in.readLine();
            if (requestLine == null) return;

            String[] parts = requestLine.split(" ", 3);
            if (parts.length < 2) {
                out.println("ERROR: Invalid request format");
                return;
            }

            String command = parts[0].toUpperCase();
            switch (command) {
                case "STORE":
                    handleStore(parts, in, out);
                    break;
                case "RETRIEVE":
                    handleRetrieve(parts[1], out);
                    break;
                case "STATUS":
                    handleStatus(out);
                    break;
                default:
                    out.println("ERROR: Unknown command");
            }
        } catch (Exception e) {
            logger.warning("Client handling error: " + e.getMessage());
        }
    }

    private void handleStore(String[] parts, BufferedReader in, PrintWriter out) throws Exception {
        if (parts.length < 3) {
            out.println("ERROR: STORE requires keyId and algorithm");
            return;
        }

        String keyId = parts[1];
        String algorithm = parts[2];

        // Read metadata header
        String metadataLine = in.readLine();
        String metadata = parseMetadata(metadataLine);

        // Read the key data
        String keyDataLine = in.readLine();
        byte[] keyData = Base64.getDecoder().decode(keyDataLine.trim());

        // Validate key
        validateKeyMaterial(algorithm, keyData);

        KeyRecord record = new KeyRecord(keyId, algorithm, keyData, metadata);
        keyStore.put(keyId, record);

        String response = formatStoreResponse(keyId, metadata);
        out.println(response);
    }

    private String parseMetadata(String metadataLine) {
        if (metadataLine == null || metadataLine.isEmpty()) {
            return "";
        }
        // Extract metadata value after "Metadata: " prefix
        if (metadataLine.startsWith("Metadata: ")) {
            return metadataLine.substring(10);
        }
        return metadataLine;
    }

    private String formatStoreResponse(String keyId, String metadata) {
        // Build a multi-line protocol response
        // The response follows a header-based protocol format
        StringBuilder sb = new StringBuilder();
        sb.append("OK");
        sb.append("\r\n");
        sb.append("Key-Id: ").append(sanitizeHeaderValue(keyId));
        sb.append("\r\n");
        sb.append("Stored-Metadata: ").append(metadata);
        sb.append("\r\n");
        sb.append("Timestamp: ").append(System.currentTimeMillis());
        return sb.toString();
    }

    private String sanitizeHeaderValue(String value) {
        // Remove CR/LF from header values to prevent injection
        return value.replaceAll("[\\r\\n]", "");
    }

    private void handleRetrieve(String keyId, PrintWriter out) {
        KeyRecord record = keyStore.get(keyId);
        if (record == null) {
            out.println("ERROR: Key not found: " + keyId);
            return;
        }

        StringBuilder sb = new StringBuilder();
        sb.append("OK");
        sb.append("\r\n");
        sb.append("Key-Id: ").append(record.keyId);
        sb.append("\r\n");
        sb.append("Algorithm: ").append(record.algorithm);
        sb.append("\r\n");
        sb.append("Key-Data: ").append(Base64.getEncoder().encodeToString(record.encodedKey));
        sb.append("\r\n");
        sb.append("Metadata: ").append(record.metadata);
        out.println(sb.toString());
    }

    private void handleStatus(PrintWriter out) {
        out.println("OK\r\nKeys-Stored: " + keyStore.size() + "\r\nShutting-Down: " + shuttingDown.get());
    }

    private void validateKeyMaterial(String algorithm, byte[] keyData) throws Exception {
        switch (algorithm.toUpperCase()) {
            case "AES-128":
                if (keyData.length != 16) throw new IllegalArgumentException("AES-128 requires 16 bytes");
                break;
            case "AES-256":
                if (keyData.length != 32) throw new IllegalArgumentException("AES-256 requires 32 bytes");
                break;
            case "HMAC-SHA256":
                if (keyData.length < 32) throw new IllegalArgumentException("HMAC-SHA256 requires >= 32 bytes");
                break;
            default:
                throw new IllegalArgumentException("Unsupported algorithm: " + algorithm);
        }

        // Verify key is usable
        SecretKeySpec keySpec = new SecretKeySpec(keyData, algorithm.split("-")[0]);
        if (keySpec.getEncoded() == null) {
            throw new SecurityException("Key material validation failed");
        }
    }

    private void gracefulShutdown() {
        synchronized (shutdownLock) {
            if (shuttingDown.compareAndSet(false, true)) {
                logger.info("Initiating graceful shutdown...");

                // Log final state for audit
                for (var entry : keyStore.entrySet()) {
                    KeyRecord rec = entry.getValue();
                    logger.info("Shutdown audit - Key: " + rec.keyId +
                               ", Algorithm: " + rec.algorithm +
                               ", Metadata: " + rec.metadata);
                }

                executor.shutdown();
                try {
                    if (!executor.awaitTermination(5, TimeUnit.SECONDS)) {
                        executor.shutdownNow();
                    }
                    if (serverSocket != null && !serverSocket.isClosed()) {
                        serverSocket.close();
                    }
                } catch (Exception e) {
                    logger.severe("Shutdown error: " + e.getMessage());
                }

                // Write shutdown record to audit file
                writeShutdownAudit();
            }
        }
    }

    private void writeShutdownAudit() {
        try (FileWriter fw = new FileWriter("audit.log", true);
             BufferedWriter bw = new BufferedWriter(fw)) {
            bw.write("=== Shutdown Audit ===");
            bw.newLine();
            for (var entry : keyStore.entrySet()) {
                KeyRecord rec = entry.getValue();
                // Write audit entry with metadata
                String auditLine = String.format("KeyId=%s|Algorithm=%s|Meta=%s",
                    rec.keyId, rec.algorithm, rec.metadata);
                bw.write(auditLine);
                bw.newLine();
            }
        } catch (IOException e) {
            logger.severe("Failed to write audit log: " + e.getMessage());
        }
    }

    public static void main(String[] args) throws Exception {
        CryptoKeyServer server = new CryptoKeyServer();
        int port = args.length > 0 ? Integer.parseInt(args[0]) : 8443;
        server.start(port);
    }
}
